        }else{
        if($p['applied']||$p['dismissed'])throw new LifeError('This proposal has already been handled.',409);
        if($p['kind']==='memory.save'){if(count($s['memories'])>=500)throw new LifeError('Memory limit reached.');$p['memoryId']=LifeStore::id();$s['memories'][]=['id'=>$p['memoryId'],'text'=>LifeStore::text($p['text'],2000,true),'updatedAt'=>LifeStore::now()];$s['memoryEpoch']=($s['memoryEpoch']??0)+1;foreach($s['conversations'] as &$c)$c['summary']='';unset($c);$result=$board;
        }elseif($p['kind']==='map.create'){
        $result=$board;$ids=[];$group=mb_substr($p['title']?:'My thinking',0,60).' · '.substr($p['id'],0,6);foreach($p['nodes'] as $i=>$node){$result=$this->store->mutate($result['version'],'map.save',['title'=>$node['title'],'kind'=>$node['kind'],'group'=>$group,'x'=>80+($i%4)*400,'y'=>80+(int)floor($i/4)*260]);$ids[]=end($result['state']['mapNodes'])['id'];if($node['parent']>=0)$result=$this->store->mutate($result['version'],'map.connect',['from'=>$ids[$node['parent']],'to'=>$ids[$i]]);}$p['nodeIds']=$ids;$p['group']=$group;$p['afterVersion']=$result['version'];
        }else{
        $week=LifeStore::week();$action=match($p['kind']){'task.create'=>'task.save','task.schedule'=>'task.schedule','sprint.goal'=>'sprint.save','goal.create'=>'goal.save',default=>throw new LifeError('Unsupported proposal.')};$params=match($p['kind']){'goal.create'=>['title'=>$p['title'],'notes'=>$p['text'],'type'=>$p['goalType'],'period'=>$p['period'],'category'=>'Personal'],'task.create'=>['title'=>$p['title'],'notes'=>$p['text'],'listId'=>$p['listId']],'task.schedule'=>['id'=>$p['recordId'],'date'=>$p['date'],'time'=>$p['time'],'minutes'=>$p['minutes']],'sprint.goal'=>array_merge($board['state']['sprints'][$week]??['taskIds'=>[]],['week'=>$week,'goal'=>$p['text']])};
        if($p['kind']==='task.schedule'){$ti=self::find($board['state']['tasks'],$p['recordId']);$old=$board['state']['tasks'][$ti]['schedule']??null;$p['undoAction']='task.schedule';$p['undoArgs']=['id'=>$p['recordId'],'date'=>$old['date']??'','time'=>$old['time']??'09:00','minutes'=>$old['minutes']??60];}
        if($p['kind']==='sprint.goal'){$p['undoAction']='sprint.save';$p['undoArgs']=array_merge($board['state']['sprints'][$week]??['taskIds'=>[],'goal'=>''],['week'=>$week]);}
        $result=$this->store->mutate($board['version'],$action,$params);if($p['kind']==='task.create'){$p['undoAction']='task.archive';$p['undoArgs']=['id'=>$result['state']['tasks'][count($result['state']['tasks'])-1]['id']];}if($p['kind']==='goal.create'){$p['undoAction']='goal.archive';$p['undoArgs']=['id'=>end($result['state']['goals'])['id']];}$p['afterVersion']=$result['version'];}
        $p['applied']=true;$p['appliedAt']=LifeStore::now();}
        $updated=$this->write($version,$s);$db->commit();return $updated+['board'=>$result];
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
    }
}
